--!strict
local Players=game:GetService("Players");local Profiles=require(script.Parent.Services.PlayerProfileService);local Service=require(script.Parent.Services.TutorialService);local remotes=require(script.Parent.Services.RemoteService).Ensure();local rate:{[Player]:number}={}
local function ready(p:Player)task.spawn(function()local deadline=os.clock()+20;while not Profiles.IsProfileLoaded(p)and os.clock()<deadline do task.wait(.2)end;if Profiles.IsProfileLoaded(p)then Service.Send(p)end end)end;Players.PlayerAdded:Connect(ready);for _,p in Players:GetPlayers()do ready(p)end;remotes.CompleteTutorial.OnServerEvent:Connect(function(p)if os.clock()-(rate[p]or 0)>.5 then rate[p]=os.clock();Service.Complete(p)end end);remotes.RestartTutorial.OnServerEvent:Connect(function(p)Service.Restart(p)end)
